#include<iostream>
#include<vector>
#include<algorithm>
#include<numeric>
#include<climits>



using namespace std;


void printVec(vector<int>& temp){
    for(const auto& elem : temp){
        std::cout<<" ,"<<elem;
    }
    std::cout<<std::endl;
}


//amar bhava samadhan
class Solution {
public:
    long long gcdSum(vector<int>& nums) {

        vector<int> prefixGCD;
        int maxElem = nums[0];
        for(size_t i=0; i<nums.size(); ++i){
            if(nums[i] > maxElem) maxElem = nums[i];   
            prefixGCD.push_back(gcd(maxElem,nums[i]));
        }
        sort(prefixGCD.begin(),prefixGCD.end());
        printVec(prefixGCD);
        
        long long sumOfGcdValues = 0;
        int i=0;
        int j=prefixGCD.size()-1;
        while(i<j){
            sumOfGcdValues += gcd(prefixGCD[i],prefixGCD[j]);
            std::cout<<"sumOfGcdValues : "<<sumOfGcdValues<<std::endl;
            i++;
            j--;
        }

        return sumOfGcdValues;
    }
};

